INSERT INTO `config_info` VALUES (1,'application-chain.yml','alarm-all','integration:\n  skywalking:\n    nacos:\n      url: http://172.30.94.79:8848/nacos/v2/cs/config\n      namespaceId: st-observable\n      dataId: alarm.default.alarm-settings\n      group: skywalking-oap\n      core:\n       auth:\n        server:\n         identity:\n          key: nacos\n          value: Devops@2025\n    oap:\n      url: http://127.0.0.1:12800/graphql\n  \n\nauth:\n  excludeUrls:\n  includeUrls: /event/**,/rule/**,/metrics/**\n\nmybatis-plus:\n  configuration:\n    log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  mapper-locations: classpath:/mapper/**/*.xml  ','95cb636d375e3aba27e28bd7e0df6260','2025-05-29 08:57:15','2025-05-29 11:45:27','nacos','10.5.168.174','','st-observable','','','','yaml','',''),(3,'application.yml','alarm-all','# Tomcat\nserver:\n  tomcat:\n    uri-encoding: UTF-8\n    max-connections: 100000\n    connection-timeout: 180000\n  port: 19000\n  servlet:\n    context-path: /alarm\n\nmanagement:\n  endpoints:\n    enabled-by-default: false\n  endpoint:\n    health:\n      enabled: true\n\nspring:\n  datasource:\n    dynamic:\n      strict: false\n      primary: rdb\n      datasource:\n        rdb:\n          ########## mysql driver config ##########\n          url: jdbc:mysql://172.30.94.79:23306/aiops_alarm?useUnicode=true&characterEncoding=UTF-8&serverTimezone=Asia/Shanghai\n          username: root\n          password: 5wTOkcpffV17Okj6\n          driver-class-name: com.mysql.cj.jdbc.Driver\n          ########## dm driver config ##########\n          #driver-class-name: dm.jdbc.driver.DmDriver\n          #url: jdbc:dm://127.0.0.1:5236/AIOPS_ALARM?useUnicode=true&characterEncoding=UTF-8&serverTimezone=Asia/Shanghai\n          #username: AIOPS_ALARM\n          #password: dm-passwd\n        doris:\n          url: jdbc:mysql://172.30.94.79:9030/aiops_alarm?useUnicode=true&characterEncoding=UTF-8&serverTimezone=Asia/Shanghai\n          username: observable\n          password: 1qazZAQ!\n          driver-class-name: com.mysql.cj.jdbc.Driver\n      druid:\n        initial-size: 10\n        max-active: 40\n        min-idle: 10\n        max-wait: 60000\n        pool-prepared-statements: true\n        max-pool-prepared-statement-per-connection-size: 20\n        time-between-eviction-runs-millis: 60000\n        min-evictable-idle-time-millis: 300000\n        test-while-idle: true\n        test-on-borrow: false\n        test-on-return: false\n\nmanager:\n  esight:\n    sub-url: https://127.0.0.1:32102/rest/openapi/notification\n    token-url: https://127.0.0.1:31943/rest/plat/smapp/v1/oauth/token\n    type: common\n    sub-uri: alarm\n    username: starroute@401\n    value: Star@1q2w\n    open-id: JhSew0QMcaCBqkWIDZ9msipXFu1KbdL2 \n    # 第三方系统服务器设置界面中的通道标识。\n    # 菜单路径为:在eSight运维面主菜单中选择“系统管理 > 北向设置 > 北向接口”。在左侧导航树中选择“RESTful回调”。\n    system-id: starroute\n    filter-condition:\n    location-site:\n    filter-infos:\n    description:\n    data-type: JSON\n  fd:\n    domain: https://127.0.0.1\n    sub-uri: /redfish/v1/EventService/Subscriptions\n    # 多个用,分隔\n    event-types: Alert\n    context:\n    protocol: Redfish\n    # true or false\n    verify-certificate: true\n    user: rootRedfish:Huawei12#$\n  api:\n    verify:\n      enable: true\n      # 多个ip用“,”分隔\n      white_ip: 127.0.0.1\n      include_urls: /api/v1/alarm/**\n  auth:\n    excludeUrls:\n    includeUrls: /assign/policy/**,/block/rule/**,/notice/**,/custom/label/**,/label/tpl/**,/event/**,/monitor/system/**,/notify/channel/**,/decision/condition/**,/notify/group/**,/notify/policy/**,/alarm/**,/statistics/**,/auth/**,/analysis/**,/top/dataGroup,/push/policy/**\n\nanalyser:\n  doris:\n    host: 172.30.94.79\n    port: 8030\n    user: observable\n    passwd: 1qazZAQ!\n  consumer:\n  # 批量消费事件，size和timeout(unit: millisecond)任一条件达成开始处理\n    batch:\n      size: 1000\n      timeout: 1000\n  # 批量写入，size和timeout(unit: millisecond)任一条件达成开始处理\n  write:\n    batch:\n      size: 3000\n      timeout: 3000\n    \n  \n\nnotify:\n\n  msg:\n    url: https://pretest.xfpaas.com/dripsms/sms\n  mrsrMsg:\n    url: http://127.0.0.1:8081/mrsr/rest/message/send\n  mail:\n    pack: 1  # pack all tos in one mail\n  #zhptMsg:\n    #url: https://jyaq.moe.edu.cn/www/zhpt/interface/SMSInterface  \n  txnlptMsg:\n    tokenUrl: http://127.0.0.1:19000/alarm/api/v1/txnlpt/oauth/token\n    sendUrl: http://127.0.0.1:19000/alarm/api/v1/txnlpt/sms-service-business/sendSms\n\n','ae4263c7d3cb220f0fc82f8f88b22b3f','2025-05-29 08:57:15','2025-05-29 11:44:28','nacos','10.5.168.174','','st-observable','','','','yaml','',''),(5,'application.yaml','auth-all','# Tomcat\nserver:\n  tomcat:\n    uri-encoding: UTF-8\n    max-threads: 1000\n    min-spare-threads: 30\n    max-connections: 100000  #最大连接数\n    connection-timeout: 180000 #连接超时\n  port: 9004\n  connection-timeout: 180000ms\n  servlet:\n    context-path: /auth\n\nnginx:\n  url: http://172.30.94.78:80\n\ncaptcha:\n  # 如果项目中使用到了redis，滑块验证码会自动把验证码数据存到redis中， 这里配置redis的key的前缀,默认是captcha:slider\n  prefix: captcha\n  # 验证码过期时间，默认是2分钟,单位毫秒， 可以根据自身业务进行调整\n  expire:\n    # 默认缓存时间 2分钟\n    default: 10000\n    # 针对 点选验证码 过期时间设置为 2分钟， 因为点选验证码验证比较慢，把过期时间调整大一些\n    WORD_IMAGE_CLICK: 20000\n  # 使用加载系统自带的资源， 默认是 false\n  init-default-resource: false\n  cache:\n    # 缓存控制， 默认为false不开启\n    enabled: true\n    # 验证码会提前缓存一些生成好的验证数据， 默认是20\n    cacheSize: 20\n    # 缓存拉取失败后等待时间 默认是 5秒钟\n    wait-time: 5000\n    # 缓存检查间隔 默认是2秒钟\n    period: 2000\n    secondary:\n      # 二次验证， 默认false 不开启\n      enabled: false\n      # 二次验证过期时间， 默认 2分钟\n      expire: 120000\n      # 二次验证缓存key前缀，默认是 captcha:secondary\n      keyPrefix: \"captcha:secondary\"\n\ntoken:\n  expire:\n    access-token-expire: 60 #token 过期时间 单位分钟\n    refresh-token-expire: 120 #refreshToken 过期时间 单位分钟\nuser:\n    expire: 30 #用户信息过期时间，单位天    \n\nauthentication:\n  type: inner #认证有三种类型 inner/sso/uap\n\ninner:\n  auth:\n    excludeUrls: /login,/captcha,/logout,/refreshToken,/loginInfo,/authChange,/authentication/authorization/applications,/authentication/authorization/dataGroups,/authentication/authorization/dataGroupName,/permission/**,/metaAndMenu/**,/initCipherData # 认证和授权不进行拦截的路径\n  apiPermission:\n    excludeUrls: /auth/workspace,/auth/guideState,/auth/userBaseInfo,/auth/updateUser,/auth/updatePassword,/auth/menu\n\ncache:\n type: redis  # 可选值redis，local\n\nspring:\n  redis:\n    # 单例模式\n    host: 172.30.94.79\n    port: 6379\n    password: DiIegiS2qGCVe7Cw\n\n    # 集群模式\n    #    cluster:\n    #      nodes: 127.0.0.1:6379,127.0.0.2:6379,127.0.0.3:6379\n    #      max-redirects: 3  # 重定向的最大次数\n    #    password: redis-password\n\n    # 哨兵模式\n    #    sentinel:\n    #      master: mymaster\n    #      nodes: 127.0.0.1:6379,127.0.0.2:6379,127.0.0.3:6379\n    #    password: redis-password\n\n    database: 0   # 数据库索引，默认0\n    timeout: 5000  # 连接超时，单位ms\n    lettuce: # 或lettuce, 连接池配置，springboot2.0中使用jedis或者lettuce配置连接池，默认为lettuce连接池\n      pool:\n        max-active: 8 # 连接池最大连接数（使用负值表示没有限制）\n        max-wait: -1 # 连接池分配连接最大阻塞等待时间（阻塞时间到，抛出异常。使用负值表示无限期阻塞）\n        max-idle: 8 # 连接池中的最大空闲连接数\n        min-idle: 4 # 连接池中的最小空闲连接数\n  # jackson时间格式化\n  jackson:\n    #time-zone: GMT+8\n    #date-format: yyyy-MM-dd HH:mm:ss\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      ######### DM数据库配置 start #########\n      #driver-class-name: dm.jdbc.driver.DmDriver\n      #url: jdbc:dm://127.0.0.1:5236/AIOPS_RESOURCE?useUnicode=true&characterEncoding=UTF-8&serverTimezone=Asia/Shanghai\n      #username: SYSDBA\n      #password: SYSDBA\n      ######### DM数据库配置 end #########\n      ######### Mysql数据库配置 start #########\n      driver-class-name: com.mysql.jdbc.Driver\n      url: jdbc:mysql://172.30.94.79:23306/aiops_resource?useUnicode=true&characterEncoding=UTF-8&serverTimezone=Asia/Shanghai\n      username: root\n      password: 5wTOkcpffV17Okj6\n      ######### Mysql数据库配置 end #########\n      ######### doris数据库配置 start #########\n     # driver-class-name: com.mysql.jdbc.Driver\n     # url: jdbc:mysql://127.0.0.1:9030/aiops_resource?characterEncoding=utf-8&useSSL=false&serverTimezone=Asia/Shanghai\n     # username: doris-user\n     # password: doris-password\n      ######### doris数据库配置 end #########\n      initial-size: 10\n      max-active: 100\n      min-idle: 10\n      max-wait: 60000\n      pool-prepared-statements: true\n      max-pool-prepared-statement-per-connection-size: 20\n      time-between-eviction-runs-millis: 60000\n      min-evictable-idle-time-millis: 300000\n      #Oracle需要打开注释\n      #validation-query: SELECT 1 FROM DUAL\n      test-while-idle: true\n      test-on-borrow: false\n      test-on-return: false\n      stat-view-servlet:\n        enabled: true\n        url-pattern: /druid/*\n        #login-username: admin\n        #login-password: admin\n      filter:\n        stat:\n          log-slow-sql: true\n          slow-sql-millis: 1000\n          merge-sql: false\n        wall:\n          config:\n            multi-statement-allow: true\n      \n\nuap: #集成uap 相关配置\n  rest-server-url: http://127.0.0.1:8380/uap-server/rest #uap-server服务认证地址\n  app-code: yy_1718692937666 #当前应用编码(uap-manager应用管理菜单中获取)\n  app-auth-code: LJI313WJACZP3YJAGHGFIM0NFCLSYL78   \n\n  \n## 初始化超管账号及超管关系，填写账号，多个英文逗号分隔。已存在但未配置的超管关系会移除，用户会保留\ninit-admin-account: admin\n\n# 部署方式 single独立部署，all非独立部署。默认all，有独立部署需求的再改。\ndeploy_mode: all\n\nsecurity:\n  select: default  #default=不开启加密 san=三未信安加密  haitai=海泰加密\n\n## 利川用\nsign:\n  san:\n    key:\n      id: SM4_test #根据环境对应修改\n    app:\n      id: app1  #根据环境对应修改\n      pws: Aa123456 #根据环境对应修改\n    config:\n      path: /data/service/auth-all/config/swsds.ini #根据打包后的swsds.ini具体位置修改\n  haitai:\n    keyId: 45def5d8dc82452db034311f17ec602f #数据唯一密钥，可以不传，不传海泰平台会自己生成，会使得同一个字符多次加密后的字符串不一致，获取的话可以通过postman调用海泰的密钥生成接口获取\n    appCode: 9549e2d10c3b406bb5f6ac7bd07d2fba #应用code,需要海泰管理员创建发放\n    url: http://127.0.0.1:18849 #机密性海泰密码服务平台地址\n    integralityUrl: http://127.0.0.1:8083 #完整性海泰密码服务平台地址\n\n\nmanagement:\n  endpoints:\n    enabled-by-default: false\n  endpoint:\n    health:\n      enabled: true \n  \n\n','aca16f2c509083004cb973d341987e3e','2025-05-29 08:57:15','2025-05-29 09:04:20','nacos','10.5.168.174','','st-observable','','','','yaml','',''),(7,'config.json','gse-service','{\n  \"server_addr\": \"\",\n  \"port\": 8090,\n \n  \"nodeman_domain\": \"st-nodeman\",\n  \"skip_auth\": false,\n  \"swagger_enable\": false,\n  \"data_base\": {\n    \"drive\": \"mysql\",\n    \"host\": \"172.30.94.79\",\n    \"port\": \"23306\",\n    \"user\": \"root\",\n    \"pwd\": \"5wTOkcpffV17Okj6\",\n    \"database\": \"bo_nodeman\",\n    \"show_sql\": true\n  },\n  \"redis\": {\n    \"addrs\": \"172.30.94.79:6379\",\n    \"password\": \"DiIegiS2qGCVe7Cw\",\n    \"masterName\": \"\",\n    \"redisType\": \"\",\n    \"db\": 1\n  },\n \n  \"log_path\": \"/data/logs/bk_gse\",\n  \"mode\": \"dev\"\n}\n','8b46dca685645609f6295af92ff30277','2025-05-29 08:57:15','2025-05-29 09:19:07','nacos','10.5.168.174','','st-observable','','','','json','',''),(9,'config.toml','n9e-service','[global]\nRunMode = \"release\"\n[Log]\nDir = \"/data/service/n9e_service/log\"\nLevel = \"DEBUG\"\nOutput = \"file\"\nRotateSize=200\nRotateNum=10\nKeepHours=0\n[HTTP]\nHost = \"0.0.0.0\"\nPort = 17000\nCertFile = \"\"\nKeyFile = \"\"\nPrintAccessLog = false\nPProf = false\nExposeMetrics = true\nShutdownTimeout = 30\nMaxContentLength = 67108864\nReadTimeout = 20\nWriteTimeout = 600\nIdleTimeout = 120\nNoSignIn = false\n\n[HTTP.Pushgw]\nEnable = true\n# [HTTP.Pushgw.BasicAuth]\n# user001 = \"ccc26da7b9aba533cbb263a36c07dcc5\"\n\n[HTTP.Alert]\nEnable = true\n[HTTP.Alert.BasicAuth]\nuser001 = \"ccc26da7b9aba533cbb263a36c07dcc5\"\n\n[HTTP.Heartbeat]\nEnable = true\n# [HTTP.Heartbeat.BasicAuth]\n# user001 = \"ccc26da7b9aba533cbb263a36c07dcc5\"\n\n[HTTP.Service]\nEnable = true\n[HTTP.Service.BasicAuth]\nuser001 = \"ccc26da7b9aba533cbb263a36c07dcc5\"\n\n[HTTP.JWTAuth]\n# signing key\nSigni