/*!40000 ALTER TABLE `his_config_info` DISABLE KEYS */;
INSERT INTO `his_config_info` VALUES (0,1,'application-chain.yml','alarm-all','','integration:\n  skywalking:\n    nacos:\n      url: http://127.0.0.1:8848/nacos/v2/cs/config\n      namespaceId: st-observable\n      dataId: alarm.default.alarm-settings\n      group: skywalking-oap\n      core:\n       auth:\n        server:\n         identity:\n          key: nacos\n          value: nacos\n    oap:\n      url: http://127.0.0.1:12800/graphql\n  \n\nauth:\n  excludeUrls:\n  includeUrls: /event/**,/rule/**,/metrics/**\n\nmybatis-plus:\n  configuration:\n    log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  mapper-locations: classpath:/mapper/**/*.xml  ','5bad1904661fd0a43b4d042bf8ec367b','2025-05-29 08:57:15','2025-05-29 08:57:15','nacos','10.5.168.174','I','st-observable',''),(0,3,'application.yml','alarm-all','','# Tomcat\nserver:\n  tomcat:\n    uri-encoding: UTF-8\n    max-connections: 100000\n    connection-timeout: 180000\n  port: 19000\n  servlet:\n    context-path: /alarm\n\nmanagement:\n  endpoints:\n    enabled-by-default: false\n  endpoint:\n    health:\n      enabled: true\n\nspring:\n  datasource:\n    dynamic:\n      strict: false\n      primary: rdb\n      datasource:\n        rdb:\n          ########## mysql driver config ##########\n          url: jdbc:mysql://127.0.0.1:3306/aiops_alarm?useUnicode=true&characterEncoding=UTF-8&serverTimezone=Asia/Shanghai\n          username: mysql-user\n          password: mysql-passwd\n          driver-class-name: com.mysql.cj.jdbc.Driver\n          ########## dm driver config ##########\n          #driver-class-name: dm.jdbc.driver.DmDriver\n          #url: jdbc:dm://127.0.0.1:5236/AIOPS_ALARM?useUnicode=true&characterEncoding=UTF-8&serverTimezone=Asia/Shanghai\n          #username: AIOPS_ALARM\n          #password: dm-passwd\n        doris:\n          url: jdbc:mysql://127.0.0.1:9030/aiops_alarm?useUnicode=true&characterEncoding=UTF-8&serverTimezone=Asia/Shanghai\n          username: doris-user\n          password: doris-passwd\n          driver-class-name: com.mysql.cj.jdbc.Driver\n      druid:\n        initial-size: 10\n        max-active: 40\n        min-idle: 10\n        max-wait: 60000\n        pool-prepared-statements: true\n        max-pool-prepared-statement-per-connection-size: 20\n        time-between-eviction-runs-millis: 60000\n        min-evictable-idle-time-millis: 300000\n        test-while-idle: true\n        test-on-borrow: false\n        test-on-return: false\n\nmanager:\n  esight:\n    sub-url: https://127.0.0.1:32102/rest/openapi/notification\n    token-url: https://127.0.0.1:31943/rest/plat/smapp/v1/oauth/token\n    type: common\n    sub-uri: alarm\n    username: starroute@401\n    value: Star@1q2w\n    open-id: JhSew0QMcaCBqkWIDZ9msipXFu1KbdL2 \n    # 第三方系统服务器设置界面中的通道标识。\n    # 菜单路径为:在eSight运维面主菜单中选择“系统管理 > 北向设置 > 北向接口”。在左侧导航树中选择“RESTful回调”。\n    system-id: starroute\n    filter-condition:\n    location-site:\n    filter-infos:\n    description:\n    data-type: JSON\n  fd:\n    domain: https://127.0.0.1\n    sub-uri: /redfish/v1/EventService/Subscriptions\n    # 多个用,分隔\n    event-types: Alert\n    context:\n    protocol: Redfish\n    # true or false\n    verify-certificate: true\n    user: rootRedfish:Huawei12#$\n  api:\n    verify:\n      enable: true\n      # 多个ip用“,”分隔\n      white_ip: 127.0.0.1\n      include_urls: /api/v1/alarm/**\n  auth:\n    excludeUrls:\n    includeUrls: /assign/policy/**,/block/rule/**,/notice/**,/custom/label/**,/label/tpl/**,/event/**,/monitor/system/**,/notify/channel/**,/decision/condition/**,/notify/group/**,/notify/policy/**,/alarm/**,/statistics/**,/auth/**,/analysis/**,/top/dataGroup,/push/policy/**\n\nanalyser:\n  doris:\n    host: 127.0.0.1\n    port: 8030\n    user: doris-user\n    passwd: doris-passwd\n  consumer:\n  # 批量消费事件，size和timeout(unit: millisecond)任一条件达成开始处理\n    batch:\n      size: 1000\n      timeout: 1000\n  # 批量写入，size和timeout(unit: millisecond)任一条件达成开始处理\n  write:\n    batch:\n      size: 3000\n      timeout: 3000\n    \n  \n\nnotify:\n\n  msg:\n    url: https://pretest.xfpaas.com/dripsms/sms\n  mrsrMsg:\n    url: http://127.0.0.1:8081/mrsr/rest/message/send\n  mail:\n    pack: 1  # pack all tos in one mail\n  #zhptMsg:\n    #url: https://jyaq.moe.edu.cn/www/zhpt/interface/SMSInterface  \n  txnlptMsg:\n    tokenUrl: http://127.0.0.1:19000/alarm/api/v1/txnlpt/oauth/token\n    sendUrl: http://127.0.0.1:19000/alarm/api/v1/txnlpt/sms-service-business/sendSms\n\n','f76a9da54e91e49c169505f09641bc85','2025-05-29 08:57:15','2025-05-29 08:57:15','nacos','10.5.168.174','I','st-observable',''),(0,5,'application.yaml','auth-all','','# Tomcat\nserver:\n  tomcat:\n    uri-encoding: UTF-8\n    max-threads: 1000\n    min-spare-threads: 30\n    max-connections: 100000  #最大连接数\n    connection-timeout: 180000 #连接超时\n  port: 9004\n  connection-timeout: 180000ms\n  servlet:\n    context-path: /auth\n\nnginx:\n  url: http://127.0.0.1\n\ncaptcha:\n  # 如果项目中使用到了redis，滑块验证码会自动把验证码数据存到redis中， 这里配置redis的key的前缀,默认是captcha:slider\n  prefix: captcha\n  # 验证码过期时间，默认是2分钟,单位毫秒， 可以根据自身业务进行调整\n  expire:\n    # 默认缓存时间 2分钟\n    default: 10000\n    # 针对 点选验证码 过期时间设置为 2分钟， 因为点选验证码验证比较慢，把过期时间调整大一些\n    WORD_IMAGE_CLICK: 20000\n  # 使用加载系统自带的资源， 默认是 false\n  init-default-resource: false\n  cache:\n    # 缓存控制， 默认为false不开启\n    enabled: true\n    # 验证码会提前缓存一些生成好的验证数据， 默认是20\n    cacheSize: 20\n    # 缓存拉取失败后等待时间 默认是 5秒钟\n    wait-time: 5000\n    # 缓存检查间隔 默认是2秒钟\n    period: 2000\n    secondary:\n      # 二次验证， 默认false 不开启\n      enabled: false\n      # 二次验证过期时间， 默认 2分钟\n      expire: 120000\n      # 二次验证缓存key前缀，默认是 captcha:secondary\n      keyPrefix: \"captcha:secondary\"\n\ntoken:\n  expire:\n    access-token-expire: 60 #token 过期时间 单位分钟\n    refresh-token-expire: 120 #refreshToken 过期时间 单位分钟\nuser:\n    expire: 30 #用户信息过期时间，单位天    \n\nauthentication:\n  type: inner #认证有三种类型 inner/sso/uap\n\ninner:\n  auth:\n    excludeUrls: /login,/captcha,/logout,/refreshToken,/loginInfo,/authChange,/authentication/authorization/applications,/authentication/authorization/dataGroups,/authentication/authorization/dataGroupName,/permission/**,/metaAndMenu/**,/initCipherData # 认证和授权不进行拦截的路径\n  apiPermission:\n    excludeUrls: /auth/workspace,/auth/guideState,/auth/userBaseInfo,/auth/updateUser,/auth/updatePassword,/auth/menu\n\ncache:\n type: redis  # 可选值redis，local\n\nspring:\n  redis:\n    # 单例模式\n    host: 127.0.0.1\n    port: 6379\n    password: redis-password\n\n    # 集群模式\n    #    cluster:\n    #      nodes: 127.0.0.1:6379,127.0.0.2:6379,127.0.0.3:6379\n    #      max-redirects: 3  # 重定向的最大次数\n    #    password: redis-password\n\n    # 哨兵模式\n    #    sentinel:\n    #      master: mymaster\n    #      nodes: 127.0.0.1:6379,127.0.0.2:6379,127.0.0.3:6379\n    #    password: redis-password\n\n    database: 1   # 数据库索引，默认0\n    timeout: 5000  # 连接超时，单位ms\n    lettuce: # 或lettuce, 连接池配置，springboot2.0中使用jedis或者lettuce配置连接池，默认为lettuce连接池\n      pool:\n        max-active: 8 # 连接池最大连接数（使用负值表示没有限制）\n        max-wait: -1 # 连接池分配连接最大阻塞等待时间（阻塞时间到，抛出异常。使用负值表示无限期阻塞）\n        max-idle: 8 # 连接池中的最大空闲连接数\n        min-idle: 4 # 连接池中的最小空闲连接数\n  # jackson时间格式化\n  jackson:\n    #time-zone: GMT+8\n    #date-format: yyyy-MM-dd HH:mm:ss\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      ######### DM数据库配置 start #########\n      #driver-class-name: dm.jdbc.driver.DmDriver\n      #url: jdbc:dm://127.0.0.1:5236/AIOPS_RESOURCE?useUnicode=true&characterEncoding=UTF-8&serverTimezone=Asia/Shanghai\n      #username: SYSDBA\n      #password: SYSDBA\n      ######### DM数据库配置 end #########\n      ######### Mysql数据库配置 start #########\n      driver-class-name: com.mysql.jdbc.Driver\n      url: jdbc:mysql://127.0.0.1:3306/aiops_resource?useUnicode=true&characterEncoding=UTF-8&serverTimezone=Asia/Shanghai\n      username: root\n      password: mysql-password\n      ######### Mysql数据库配置 end #########\n      ######### doris数据库配置 start #########\n     # driver-class-name: com.mysql.jdbc.Driver\n     # url: jdbc:mysql://127.0.0.1:9030/aiops_resource?characterEncoding=utf-8&useSSL=false&serverTimezone=Asia/Shanghai\n     # username: doris-user\n     # password: doris-password\n      ######### doris数据库配置 end #########\n      initial-size: 10\n      max-active: 100\n      min-idle: 10\n      max-wait: 60000\n      pool-prepared-statements: true\n      max-pool-prepared-statement-per-connection-size: 20\n      time-between-eviction-runs-millis: 60000\n      min-evictable-idle-time-millis: 300000\n      #Oracle需要打开注释\n      #validation-query: SELECT 1 FROM DUAL\n      test-while-idle: true\n      test-on-borrow: false\n      test-on-return: false\n      stat-view-servlet:\n        enabled: true\n        url-pattern: /druid/*\n        #login-username: admin\n        #login-password: admin\n      filter:\n        stat:\n          log-slow-sql: true\n          slow-sql-millis: 1000\n          merge-sql: false\n        wall:\n          config:\n            multi-statement-allow: true\n      \n\nuap: #集成uap 相关配置\n  rest-server-url: http://127.0.0.1:8380/uap-server/rest #uap-server服务认证地址\n  app-code: yy_1718692937666 #当前应用编码(uap-manager应用管理菜单中获取)\n  app-auth-code: LJI313WJACZP3YJAGHGFIM0NFCLSYL78   \n\n  \n## 初始化超管账号及超管关系，填写账号，多个英文逗号分隔。已存在但未配置的超管关系会移除，用户会保留\ninit-admin-account: admin\n\n# 部署方式 single独立部署，all非独立部署。默认all，有独立部署需求的再改。\ndeploy_mode: all\n\nsecurity:\n  select: default  #default=不开启加密 san=三未信安加密  haitai=海泰加密\n\n## 利川用\nsign:\n  san:\n    key:\n      id: SM4_test #根据环境对应修改\n    app:\n      id: app1  #根据环境对应修改\n      pws: Aa123456 #根据环境对应修改\n    config:\n      path: /data/service/auth-all/config/swsds.ini #根据打包后的swsds.ini具体位置修改\n  haitai:\n    keyId: 45def5d8dc82452db034311f17ec602f #数据唯一密钥，可以不传，不传海泰平台会自己生成，会使得同一个字符多次加密后的字符串不一致，获取的话可以通过postman调用海泰的密钥生成接口获取\n    appCode: 9549e2d10c3b406bb5f6ac7bd07d2fba #应用code,需要海泰管理员创建发放\n    url: http://127.0.0.1:18849 #机密性海泰密码服务平台地址\n    integralityUrl: http://127.0.0.1:8083 #完整性海泰密码服务平台地址\n\n\nmanagement:\n  endpoints:\n    enabled-by-default: false\n  endpoint:\n    health:\n      enabled: true \n  \n\n','f4e666c6471407462b32c5640bf742b3','2025-05-29 08:57:15','2025-05-29 08:57:15','nacos','10.5.168.174','I','st-observable',''),(0,7,'config.json','gse-service','','{\n  \"server_addr\": \"\",\n  \"port\": 8090,\n \n  \"nodeman_domain\": \"st-nodeman\",\n  \"skip_auth\": false,\n  \"swagger_enable\": false,\n  \"data_base\": {\n    \"drive\": \"mysql\",\n    \"host\": \"127.0.0.1\",\n    \"port\": \"3306\",\n    \"user\": \"root\",\n    \"pwd\": \"mysql-password\",\n    \"database\": \"bo_nodeman\",\n    \"show_sql\": true\n  },\n  \"redis\": {\n    \"addrs\": \"127.0.0.1:26379,127.0.0.2:26379,127.0.0.3:26379\",\n    \"password\": \"redis-password\",\n    \"masterName\": \"mymaster\",\n    \"redisType\": \"sentinel\",\n    \"db\": 1\n  },\n \n  \"log_path\": \"/data/logs/bk_gse\",\n  \"mode\": \"dev\"\n}\n','3f6b4eaeaa03121a05b8fd8d0abd2dd0','2025-05-29 08:57:15','2025-05-29 08:57:15','nacos','10.5.168.174','I','st-observable',''),(0,9,'config.toml','n9e-service','','[global]\nRunMode = \"release\"\n[Log]\nDir = \"/data/service/n9e_service/log\"\nLevel = \"DEBUG\"\nOutput = \"file\"\nRotateSize=200\nRotateNum=10\nKeepHours=0\n[HTTP]\nHost = \"0.0.0.0\"\nPort = 17000\nCertFile = \"\"\nKeyFile = \"\"\nPrintAccessLog = false\nPProf = false\nExposeMetrics = true\nShutdownTimeout = 30\nMaxContentLength = 67108864\nReadTimeout = 20\nWriteTimeout = 600\nIdleTimeout = 120\nNoSignIn = false\n\n[HTTP.Pushgw]\nEnable = true\n# [HTTP.Pushgw.BasicAuth]\n# user001 = \"ccc26da7b9aba533cbb263a36c07dcc5\"\n\n[HTTP.Alert]\nEnable = true\n[HTTP.Alert.BasicAuth]\nuser001 = \"ccc26da7b9aba533cbb263a36c07dcc5\"\n\n[HTTP.Heartbeat]\nEnable = true\n# [HTTP.Heartbeat.BasicAuth]\n# user001 = \"ccc26da7b9aba533cbb263a36c07dcc5\"\n\n[HTTP.Service]\nEnable = true\n[HTTP.Service.BasicAuth]\nuser001 = \"ccc26da7b9aba533cbb263a36c07dcc5\"\n\n[HTTP.JWTAuth]\n# signing key\nSigningKey = \"5b94a0fd640fe2765af826acfe42d151\"\n# unit: min\nAccessExpired = 1500\n# unit: min\nRefreshExpired = 10080\nRedisKeyPrefix = \"/jwt/\"\n\n[HTTP.ProxyAuth]\n# if proxy auth enabled, jwt auth is disabled\nEnable = true\n# username key in http proxy heade\nHeaderUserNameKey = \"X-User-Name\"\nCookieTokenKey = \"bk_token\"\nTokenCheckURL = \"auth\"\nDefaultRoles = [\"Admin\"]\n\n[HTTP.APIGateway]\nAppCode = \"bk_iam\"\nAppSecret = \"05dc121d-ec79-491c-946c-4349eb9e364b\"\nUserName = \"admin\"\nFields = \"id,username,display_name,telephone,email\"\n\n[HTTP.RSA]\n# open RSA\nOpenRSA = false\n# RSA public key\nRSAPublicKeyPath = \"/etc/n9e/public.pem\"\n# RSA private key\nRSAPrivateKeyPath = \"/etc/n9e/private.pem\"\n# RSA private key password\nRSAPassWord = \"\"\n\n[HTTP.APIForService]\nEnable = true\n\n[HTTP.APIForAgent]\nEnable = true\n\n[HTTP.ThirdParty.GSE]\nDomain = \"st-gse\"\n\n[HTTP.ThirdParty.Nodeman]\nDomain = \"st-nodeman\"\n\n[HTTP.ThirdParty.Auth]\nDomain = \"auth\"\n\n[HTTP.ThirdParty.Res]\nDomain = \"resource-manager-service\"\n\n[HTTP.ThirdParty.Alarm]\nEventUploadUrl = \"alarm-all\"\nDialtestingEventUploadUrl = \"alarm-all\"\n#DialtestingCloseSendAlarm = false   #测试专用，是否上报拨测告警\n\n[DB]\n#DSN=\"dm://N9E:dm-password@127.0.0.1:5236?schema=N9E\"\n#Debug = false\n#DBType = \"dm\"\nDSN=\"root:mysql-password@tcp(127.0.0.1:3306)/n9e_v6?charset=utf8mb4&parseTime=True&loc=Local&allowNativePasswords=true\"\nDebug = false\nDBType = \"mysql\"\nMaxLifetime = 7200\nMaxOpenConns = 150\nMaxIdleConns = 50\nTablePrefix = \"\"\n\n[Redis]\n#redis单例模式配置\n#Address = \"127.0.0.1:6379\"\n#Password = \"redis-password\"\n#RedisType = \"\"\n\n#redis哨兵模式配置\nAddress = \"127.0.0.1:26379,127.0.0.2:26379,127.0.0.3:26379\"\nPassword = \"redis-password\"\nRedisType = \"sentinel\"\nMasterName = \"mymaster\"\n\n[Alert]\n[Alert.Heartbeat]\n# auto detect if blank\nIP = \"\"\n# unit ms\nInterval = 1000\nClusterName = \"default\"\n\n[Center]\nRumYamlFile = \"rum.yaml\"\n\n[Center.AnonymousAccess]\nPromQuerier = true\nAlertDetail = true\n\n[Pushgw]\n# use target labels in database instead of in series\nLabelRewrite = true\n\n[[Pushgw.Writers]]\n# Url = \"http://127.0.0.1:8480/insert/0/prometheus/api/v1/write\" # 集群的URL示例，不要删\n# Url = \"http://127.0.0.1:8428/api/v1/write\"   #单节点的URL示例，不要删\nUrl = \"http://127.0.0.1:8428/api/v1/write\"\n# Basic auth username\nBasicAuthUser = \"\"\n# Basic auth password\nBasicAuthPass = \"\"\n# timeout settings, unit: ms\nHeaders = [\"X-From\", \"n9e\"]\nTimeout = 10000\nDialTimeout = 3000\nTLSHandshakeTimeout = 30000\nExpectContinueTimeout = 1000\nIdleConnTimeout = 90000\n# time duration, unit: ms\nKeepAlive = 30000\nMaxConnsPerHost = 0\nMaxIdleConns = 100\nMaxIdleConnsPerHost = 100\n\n[DangerousCommand]\nShells = [\"expr\", \"rm\", \"mv\", \"shutdown\", \"reboot\", \"crontab\"]\nPythons = [\"os.remove\", \"shutil.move\", \"shutdown\", \"schedule.every\", \"threading.Timer\"]\nPython3s = [\"os.remove\", \"shutil.move\", \"shutdown\", \"schedule.every\", \"threading.Timer\"]\n\n[Extend]\nDialExportManySheet = false\nDialExportMaxDays = 7\nDialExportMaxTaskCount = 1000\nDialExportFailData = true\nTargetExportMaxDays = 7\n\n[ZheJiangThreshold]\nHost=[1,1,80] # [cpu, mem, disk] 整数，不可填小数\n[ZheJiangThreshold.Redis]\ndev=2\n\"测试集群\"=3\n[ZheJiangThreshold.Rocketmq]\ncluster1=3\ncluster2=1\n[ZheJiangThreshold.Fastdfs]\ncluster1 = [2,2] # [group数量，活跃server数量] 整数\ncluster2 = [1,1] # [group数量，活跃server数量] 整数\n\n[Doris.Datasource]\nDSN=\"doris-user:doris-password@tcp(127.0.0.1:9030)/n9e?charset=utf8mb4&parseTime=True&loc=Local&allowNativePasswords=true\"\nDebug = true\nDBType = \"doris\"\nMaxLifetime = 7200\nMaxOpenConns = 150\nMaxIdleConns = 50\nTablePrefix = \"\"\n\n[Doris.StreamLoad]\nHost=\"127.0.0.1\"\nPort=\"8030\"\nDatabase=\"n9e\"\nUser=\"doris-user\"\nPassword=\"doris-password\"\nMaxFilterRatio=0.0\nLoadToSingleTablet=false\nMergeMaxSizeMb=70\nMergeMaxWaitSecond=60\nConcurrentOperatorCount=10\nFileKeepHour=48','0e0aedabf4aebb96306f7c6f5811005b','2025-05-29 08:57:15','2025-05-29 08:57:15','nacos','10.5.168.174','I','st-observable',''),(0,11,'middleware.json','n9e-service','','{\n	\"databases\": {\n		\"doris_be_cache_usage\": \"instance\",\n		\"dm_global_status_cpu_use_rate\": \"db\",\n		\"mysql_max_used_connections\": \"server\",\n		\"redis_db_keys\": \"server\",\n        \"postgresql_blks_hit\":\"server\",\n        \"elasticsearch_node_stats_os_mem_used_in_bytes\":\"cluster_name\",\n        \"etcd_disk_backend_commit_duration_seconds_sum\":\"service\",\n        \"minio_bucket_usage_object_total\":\"server\"\n	},\n    \"middlewares\": {\n        \"nginx_connection_active\": \"nginx_server\",\n        \"nacos_system_cpu_count\":\"instance\",\n        \"kafka_controller_AutoLeaderBalanceRateAndTimeMs.Max\":\"jolokia_agent_url\"\n    },\n    \"apps\": {\n        \"jvm_cpu_load_system\": \"service\"\n    }\n}','1b9335b829b728faea171303ed3f4fad','2025-05-29 08:57:15','2025-05-29 08:57:15','nacos','10.5.168.174','I','st-observable',''),(0,13,'config.json','nodeman-service','','{\n  \"server_addr\": \"\",\n  \"port\": 8091,\n  \"auth_url\": \"auth\",\n  \"gse_url\": \"st-gse\",\n  \"skip_auth\": false,\n  \"swagger_enable\": false,\n  \"data_base\": {\n    \"drive\": \"mysql\",\n    \"host\": \"127.0.0.1\",\n    \"port\": \"3306\",\n    \"user\": \"root\",\n    \"pwd\": \"mysql-password\",\n    \"database\": \"bo_nodeman\" \n  },\n  \"redis\": {\n    \"addrs\": \"127.0.0.1:26379,127.0.0.2:26379,127.0.0.3:26379\",\n    \"password\": \"redis-password\",\n    \"masterName\": \"mymaster\",\n    \"redisType\": \"sentinel\",\n    \"db\": 1\n  },\n  \"log_path\": \"/data/logs/bk_nodeman\",\n  \"mode\": \"dev\",\n  \"client_rsa_private_key\": \"-----BEGIN RSA PRIVATE KEY-----\\nMIIBOgIBAAJBANytGKbJUPHPyjtuei+1ZqwVZUywFZL+tWjzggCq5dhXSssiVVAF\\nzGgG5lEPSV4Bz6A7wPjvhXjhEFzFXXv9eQ0CAwEAAQJBAKGebJWKj6vqIRTR3s8e\\nLioOKXi25bYYschBv465m0iLmeZArSQ+mRvg5OM58yuwkK0DQztc67VQuoXGN8Ix\\nDMkCIQDt1pCgIrkJlS6x27EyaL0AlPerCxt0BHY0Hi6qxh7KEwIhAO2HCUSXYrpi\\nJYFg3GLbQ4bZ65RPQs70aOYAkO3+/RRfAiB5MVOi9e6aDnWr1cnWaP6eNEp70v4b\\nQUbGSfb3uFrqFwIgODabFOaW8PFFWwcnYSXvJzzvqdvQPdZN9RDxO8H69xUCIBiE\\nZTFZDIB/cyLxz65/7mtRLsO85f7VKrVhhUrSDn9Y\\n-----END RSA PRIVATE KEY-----\"\n}\n','ee02c06b586b1ddc45199283a34806c5','2025-05-29 08:57:15','2025-05-29 08:57:15','nacos','10.5.168.174','I','st-observable',''),(0,15,'alarm.default.alarm-settings','skywalking-oap','','\nwebhooks: [\'http://127.0.0.1:19000/alarm/api/v1/collect/adapter/trace/event\']\n','1fca1b18d7e01f17f2a5563fae00d5f6','2025-05-29 08:57:15','2025-05-29 08:57:15','nacos','10.5.168.174','I','st-observable',''),(0,17,'application-startrace.yml','ST-LOG-PLATFORM','','st-log-platform:\n  config:\n    kafka:\n      log-record-topic: test_topic # 日志记录使用的Topic\n      consumer:\n        topics-to-listen: test_topic # kafka消费topic, 默认会消费log-record-topic, 在这里可以添加额外需要消费的Topic\n    xxl-job:\n      enabled: true # 是否启用xxl-job\n      accessToken: aafb230a-1bef-411d-8853-5f3d4edebb95 # 执行器的通信令牌，非空时启用\n    storage:\n      type: doris\n    stack-error:\n      type: regex # 错误堆栈信息解析方式\n  auth-enable: true # 是否开启权限认证\n  deploy-job-enable: true\n  deploy-alarm-platform: true # 是否部署了统一告警平台\n  application-add-url: http://127.0.0.1:9005/resource/sys/application/insert # resource服务地址\n  alarm:\n    alarm-server: alarm-all # 告警平台服务地址\n    alarm-server-path: alarm # 告警平台服务Http请求前缀\n    send-alarm:\n      core-pool-size: 1\n      max-pool-size: 2\n  access:\n    vector-kafka-bootstrap-servers: ${spring.kafka.bootstrap-servers}\n    vector-topic: ${st-log-platform.config.kafka.log-record-topic} # vector写入的kafka topic\n  http-server:\n    thread-pool:\n      core-pool-size: 5\n      max-pool-size: 10\n      queue-capacity-size: 5000\n\n\nserver:\n  port: 8100\n  servlet:\n    context-path: /log-platform\n\nspring:\n  datasource:\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://${st-log-platform.config.db.url}:9030/log_platform?characterEncoding=utf-8&useSSL=false&serverTimezone=Asia/Shanghai\n    username: ${st-log-platform.config.db.username}\n    password: ${st-log-platform.config.db.password}\n    hikari:\n      maximum-pool-size: 60  # 最大连接数，默认值10\n      minimum-idle: 10  # 最小空闲连接数，默认值10\n      connection-timeout: 60000 # 连接超时时间（毫秒），默认值60000（30秒）\n      idle-timeout: 600000  # 空闲连接超时时间，默认值600000（10分钟）\n      max-lifetime: 3600000 # 连接最大存活时间，默认值1800000（30分钟）\n      connection-test-query: select 1 # 连接测试查询\n  jackson:\n    date-format: yyyy-MM-dd HH:mm:ss.SSS\n    time-zone: GMT+8\n  kafka:\n    bootstrap-servers: ${st-log-platform.config.kafka.bootstrap-servers}\n    listener:\n      concurrency: 3\n    consumer:\n      enable-auto-commit: false\n      key-deserializer: org.apache.kafka.common.serialization.StringDeserializer\n      value-deserializer: org.apache.kafka.common.serialization.StringDeserializer\n      auto-offset-reset: latest\n      max-poll-records: 10000\n      fetch-max-bytes: 10485760\n      max-partition-fetch-bytes: 10485760\n      fetch-max-wait-ms: 15000\n      fetch-min-bytes: 5242880\n      group-id: log-consumer\n      topics-to-listen: ${st-log-platform.config.kafka.log-record-topic},${st-log-platform.config.kafka.consumer.topics-to-listen}\n    producer:\n      key-serializer: org.apache.kafka.common.serialization.StringSerializer\n      value-serializer: org.apache.kafka.common.serialization.StringSerializer\n      batch-size: 163840  # single request 批处理大小（以字节为单位），默认16KB = 16384\n      properties.linger.ms: 500\n  config:\n    import: config-custom.yml\n\nmybatis-plus:\n  global-config:\n    enable-sql-runner: true\n  configuration:\n    map-underscore-to-camel-case: false\n    call-setters-on-nulls: true\n    #log-impl: org.apache.ibatis.logging.stdout.StdOutImpl #开启sql日志, 生产环境关闭\n\nmanagement:\n  endpoints:\n    enabled-by-default: false\n  endpoint:\n    health:\n      enabled: true\n  health:\n    elasticsearch:\n      enabled: false #关闭es健康自测，防止doris启动报错\n\n# xxl-job配置\nsop:\n  xxl-job:\n    enabled: ${st-log-platform.config.xxl-job.enabled}\n    admin:\n      addresses: http://${st-log-platform.config.xxl-job.admin-server-ip}:8101/xxl-job-admin # 调度中心部署地址-如调度中心集群部署存在多个地址则用逗号分隔\n    accessToken: ${st-log-platform.config.xxl-job.accessToken} # 执行器的通信令牌，非空时启用\n    executor:\n      appname: ${spring.application.name} # 与xxl-job-admin配置的appname一致\n      address:\n      ip:  # 执行器的IP地址，执行器IP默认为空，表示自动获取IP\n      port: 9999  # 执行器的端口号，默认值为9999\n      logpath: logs/xxljob\n      logretentiondays: 7\n\ndoris:\n  stream-load:\n    datasource:\n      host: ${st-log-platform.config.db.url}\n      port: 8030\n      database: log_platform\n      user: ${st-log-platform.config.db.username}\n      password: ${st-log-platform.config.db.password}\n    data:\n      dir: /data/public/st-logplatform-service/log-data-file/\n      fail-file-keep-hour: 48\n      fail-file-clear-cron: 0 0 2 * * ?\n      merge:\n        core-pool-size: 1\n        max-pool-size: 1\n        concurrent-operator-count: 1\n        max-size-mb: 70\n        max-wait-second: 60\n    send:\n      async-enable: true  #是否启用异步导入\n      max-filter-ratio: 0  # 最大容忍可过滤（数据不规范等原因）的数据比例,取值范围是0~1,例如:0.1\n      core-pool-size: 2\n      max-pool-size: 2\n    retry:\n      core-pool-size: 1\n      max-pool-size: 1\n      fail-send-cron: 0 0 */1 * * ?  #doris-stream-load失败重试定时cron\nes:\n  storage-async:\n    split:\n      core-pool-size: 1\n      max-pool-size: 2\n      queue-capacity-size: 50\n      max-wait-time: 60\n    send:\n      core-pool-size: 1\n      max-pool-size: 2\n      listSize: 500      \n\n','3d3ae6433b90632fbbab7de58e2d1ab7','2025-05-29 08:57:15','2025-05-29 08:57:15','nacos','10.5.168.174','I','st-observable',''),(0,19,'config-custom.yml','ST-LOG-PLATFORM','','st-log-platform:\n  config:\n    db:\n      url: 127.0.0.1 #数据库服务器ip\n      username: doris-user # 数据库用户\n      password:  doris-password # 数据库用户密码\n    kafka:\n      bootstrap-servers: 127.0.0.1:9092 # kafka部署地址\n    xxl-job:\n      admin-server-ip: 127.0.0.1 # xxl-job调度中心部署地址\n    grafana:\n      url: http://127.0.0.1:3000/d/ffb8ddd6-f2c9-4f6c-9e8d-8352cc99a798/nginx?orgId=1  # Grafana Nginx仪表盘地址\n    elasticsearch:\n      uris: 127.0.0.1:9200\n      username: elastic\n      password: elastic','c63fdf87318cb9d0a70fd63cdc53e75f','2025-05-29 08:57:15','2025-05-29 08:57:15','nacos','10.5.168.174','I','st-observable',''),(5,21,'application.yaml','auth-all','','# Tomcat\nserver:\n  tomcat:\n    uri-encoding: UTF-8\n    max-threads: 1000\n    min-spare-threads: 30\n    max-connections: 100000  #最大连接数\n    connection-timeout: 180000 #连接超时\n  port: 9004\n  connection-timeout: 180000ms\n  servlet:\n    context-path: /auth\n\nnginx:\n  url: http://127.0.0.1\n\ncaptcha:\n  # 如果项目中使用到了redis，滑块验证码会自动把验证码数据存到redis中， 这里配置redis的key的前缀,默认是captcha:slider\n  prefix: captcha\n  # 验证码过期时间，默认是2分钟,单位毫秒， 可以根据自身业务进行调整\n  expire:\n    # 默认缓存时间 2分钟\n    default: 10000\n    # 针对 点选验证码 过期时间设置为 2分钟， 因为点选验证码验证比较慢，把过期时间调整大一些\n    WORD_IMAGE_CLICK: 20000\n  # 使用加载系统自带的资源， 默认是 false\n  init-default-resource: false\n  cache:\n    # 缓存控制， 默认为false不开启\n    enabled: true\n    # 验证码会提前缓存一些生成好的验证数据， 默认是20\n    cacheSize: 20\n    # 缓存拉取失败后等待时间 默认是 5秒钟\n    wait-time: 5000\n    # 缓存检查间隔 默认是2秒钟\n    period: 2000\n    secondary:\n      # 二次验证， 默认false 不开启\n      enabled: false\n      # 二次验证过期时间， 默认 2分钟\n      expire: 120000\n      # 二次验证缓存key前缀，默认是 captcha:secondary\n      keyPrefix: \"captcha:secondary\"\n\ntoken:\n  expire:\n    access-token-expire: 60 #token 过期时间 单位分钟\n    refresh-token-expire: 120 #refreshToken 过期时间 单位分钟\nuser:\n    expire: 30 #用户信息过期时间，单位天    \n\nauthentication:\n  type: inner #认证有三种类型 inner/sso/uap\n\ninner:\n  auth:\n    excludeUrls: /login,/captcha,/logout,/refreshToken,/loginInfo,/authChange,/authentication/authorization/applications,/authentication/authorization/dataGroups,/authentication/authorization/dataGroupName,/permission/**,/metaAndMenu/**,/initCipherData # 认证和授权不进行拦截的路径\n  apiPermission:\n    excludeUrls: /auth/workspace,/auth/guideState,/auth/userBaseInfo,/auth/updateUser,/auth/updatePassword,/auth/menu\n\ncache:\n type: redis  # 可选值redis，local\n\nspring:\n  redis:\n    # 单例模式\n    host: 127.0.0.1\n    port: 6379\n    password: redis-password\n\n    # 集群模式\n    #    cluster:\n    #      nodes: 127.0.0.1:6379,127.0.0.2:6379,127.0.0.3:6379\n    #      max-redirects: 3  # 重定向的最大次数\n    #    password: redis-password\n\n    # 哨兵模式\n    #    sentinel:\n    #      master: mymaster\n    #      nodes: 127.0.0.1:6379,127.0.0.2:6379,127.0.0.3:6379\n    #    password: redis-password\n\n    database: 1   # 数据库索引，默认0\n    timeout: 5000  # 连接超时，单位ms\n    lettuce: # 或lettuce, 连接池配置，springboot2.0中使用jedis或者lettuce配置连接池，默认为lettuce连接池\n      pool:\n        max-active: 8 # 连接池最大连接数（使用负值表示没有限制）\n        max-wait: -1 # 连接池分配连接最大阻塞等待时间（阻塞时间到，抛出异常。使用负值表示无限期阻塞）\n        max-idle: 8 # 连接池中的最大空闲连接数\n        min-idle: 4 # 连接池中的最小空闲连接数\n  # jackson时间格式化\n  jackson:\n    #time-zone: GMT+8\n    #date-format: yyyy-MM-dd HH:mm:ss\n  datasource:\n    type: com.alibaba.druid.pool.DruidDataSource\n    druid:\n      ######### DM数据库配置 start #########\n      #driver-class-name: dm.jdbc.driver.DmDriver\n      #url: jdbc:dm://127.0.0.1:5236/AIOPS_RESOURCE?useUnicode=true&characterEncoding=UTF-8&serverTimezone=Asia/Shanghai\n      #username: SYSDBA\n      #password: SYSDBA\n      ######### DM数据库配置 end #########\n      ######### Mysql数据库配置 start #########\n      driver-class-name: com.mysql.jdbc.Driver\n      url: jdbc:mysql://127.0.0.1:3306/aiops_resource?useUnicode=true&characterEncoding=UTF-8&serverTimezone=Asia/Shanghai\n      username: root\n      password: mysql-password\n      ######### Mysql数据库配置 end #########\n      ######### doris数据库配置 start #########\n     # driver-class-name: com.mysql.jdbc.Driver\n     # url: jdbc:mysql://127.0.0.1:9030/aiops_resource?characterEncoding=utf-8&useSSL=false&serverTimezone=Asia/Shanghai\n     # username: doris-user\n     # password: doris-password\n      ######### doris数据库配置 end #########\n      initial-size: 10\n      max-active: 100\n      min-idle: 10\n      max-wait: 60000\n      pool-prepared-statements: true\n      max-pool-prepared-statement-per-connection-size: 20\n      time-between-eviction-runs-millis: 60000\n      min-evictable-idle-time-millis: 300000\n      #Oracle需要打开注释\n      #validation-query: SELECT 1 FROM DUAL\n      test-while-idle: true\n      test-on-borrow: false\n      test-on-return: false\n      stat-view-servlet:\n        enabled: true\n        url-pattern: /druid/*\n        #login-username: admin\n        #login-password: admin\n      filter:\n        stat:\n          log-slow-sql: true\n          slow-sql-millis: 1000\n          merge-sql: false\n        wall:\n          config:\n            multi-statement-allow: true\n      \n\nuap: #集成uap 相关配置\n  rest-server-url: http://127.0.0.1:8380/uap-server/rest #uap-server服务认证地址\n  app-code: yy_1718692937666 #当前应用编码(uap-manager应用管理菜单中获取)\n  app-auth-code: LJI313WJACZP3YJAGHGFIM0NFCLSYL78   \n\n  \n## 初始化超管账号及超管关系，填写账号，多个英文逗号分隔。已存在但未配置的超管关系会移除，用户会保留\ninit-admin-account: admin\n\n# 部署方式 single独立部署，all非独立部署。默认all，有独立部署需求的再改。\ndeploy_mode: all\n\nsecurity:\n  select: default  #default=不开启加密 san=三未信安加密  haitai=海泰加密\n\n## 利川用\nsign:\n  san:\n    key:\n      id: SM4_test #根据环境对应修改\n    app:\n      id: app1  #根据环境对应修改\n      pws: Aa123456 #根据环境对应修改\n    config:\n      path: /data/service/auth-all/config/swsds.ini #根据打包后的swsds.ini具体位置修改\n  haitai:\n    keyId: 45def5d8dc82452db034311f17ec602f #数据唯一密钥，可以不传，不传海泰平台会自己生成，会使得同一个字符多次加密后的字符串不一致，获取的话可以通过postman调用海泰的密钥生成接口获取\n    appCode: 9549e2d10c3b406bb5f6ac7bd07d2fba #应用code,需要海泰管理员创建发放\n    url: http://127.0.0.1:18849 #机密性海泰密码服务平台地址\n    integralityUrl: http://127.0.0.1:8083 #完整性海泰密码服务平台地址\n\n\nmanagement:\n  endpoints:\n    enabled-by-default: false\n  endpoint:\n    health:\n      enabled: true \n  \n\n','f4e666c6471407462b32c5640bf742b3','2025-05-29 09:04:19','2025-05-29 09:04:20','nacos','10.5.168.174','U','st-observable',''),(13,23,'config.json','nodeman-service','','{\n  \"server_addr\": \"\",\n  \"port\": 8091,\n  \"auth_url\": \"auth\",\n  \"gse_url\": \"st-gse\",\n  \"skip_auth\": false,\n  \"swagger_enable\": false,\n  \"data_base\": {\n    \"drive\": \"mysql\",\n    \"host\": \"127.0.0.1\",\n    \"port\": \"3306\",\n    \"user\": \"root\",\n    \"pwd\": \"mysql-password\",\n    \"database\": \"bo_nodeman\" \n  },\n  \"redis\": {\n    \"addrs\": \"127.0.0.1:26379,127.0.0.2:26379,127.0.0.3:26379\",\n    \"password\": \"redis-password\",\n    \"masterName\": \"mymaster\",\n    \"redisType\": \"sentinel\",\n    \"db\": 1\n  },\n  \"log_path\": \"/data/logs/bk_nodeman\",\n  \"mode\": \"dev\",\n  \"client_rsa_private_key\": \"-----BEGIN RSA PRIVATE KEY-----\\nMIIBOgIBAAJBANytGKbJUPHPyjtuei+1ZqwVZUywFZL+tWjzggCq5dhXSssiVVAF\\nzGgG5lEPSV4Bz6A7wPjvhXjhEFzFXXv9eQ0CAwEAAQJBAKGebJWKj6vqIRTR3s8e\\nLioOKXi25bYYschBv465m0iLmeZArSQ+mRvg5OM58yuwkK0DQztc67VQuoXGN8Ix\\nDMkCIQDt1pCgIrkJlS6x27EyaL0AlPerCxt0BHY0Hi6qxh7KEwIhAO2HCUSXYrpi\\nJYFg3GLbQ4bZ65RPQs70aOYAkO3+/RRfAiB5MVOi9e6aDnWr1cnWaP6eNEp70v4b\\nQUbGSfb3uFrqFwIgODabFOaW8PFFWwcnYSXvJzzvqdvQPdZN9RDxO8H69xUCIBiE\\nZTFZDIB/cyLxz65/7mtRLsO85f7VKrVhhUrSDn9Y\\n-----END RSA PRIVATE KEY-----\"\n}\n','ee02c06b586b1ddc45199283a34806c5','2025-05-29 09:15:21','2025-05-29 09:15:22','nacos','10.5.168.174','U','st-observable',''),(13,25,'config.json','nodeman-service','','{\n  \"server_addr\": \"\",\n  \"port\": 8091,\n  \"auth_url\": \"auth\",\n  \"gse_url\": \"st-gse\",\n  \"skip_auth\": false,\n  \"swagger_enable\": false,\n  \"data_base\": {\n    \"drive\": \"mysql\",\n    \"host\": \"172.30.94.79\",\n    \"port\": \"23306\",\n    \"user\": \"root\",\n    \"pwd\": \"5wTOkcpffV17Okj6\",\n    \"database\": \"bo_nodeman\" \n  },\n  \"redis\": {\n    \"addrs\": \"172.30.94.79:6379\",\n    \"password\": \"DiIegiS2qGCVe7Cw\",\n    \"masterName\": \"\",\n    \"redisType\": \"\",\n    \"db\": 1\n  },\n  \"log_path\": \"/data/logs/bk_nodeman\",\n  \"mode\": \"dev\",\n  \"client_rsa_private_key\": \"-----BEGIN RSA PRIVATE KEY-----\\nMIIBOgIBAAJBANytGKbJUPHPyjtuei+1ZqwVZUywFZL+tWjzggCq5dhXSssiVVAF\\nzGgG5lEPSV4Bz6A7wPjvhXjhEFzFXXv9eQ0CAwEAAQJBAKGebJWKj6vqIRTR3s8e\\nLioOKXi25bYYschBv465m0iLmeZArSQ+mRvg5OM58yuwkK0DQztc67VQuoXGN8Ix\\nDMkCIQDt1pCgIrkJlS6x27EyaL0AlPerCxt0BHY0Hi6qxh7KEwIhAO2HCUSXYrpi\\nJYFg3GLbQ4bZ65RPQs70aOYAkO3+/RRfAiB5MVOi9e6aDnWr1cnWaP6eNEp70v4b\\nQUbGSfb3uFrqFwIgODabFOaW8PFFWwcnYSXvJzzvqdvQPdZN9RDxO8H69xUCIBiE\\nZTFZDIB/cyLxz65/7mtRLsO85f7VKrVhhUrSDn9Y\\n-----END RSA PRIVATE KEY-----\"\n}\n','af582847a3109d809868ba2220d95a14','2025-05-29 09:15:27','2025-05-29 09:15:27','nacos','10.5.168.174','U','st-observable',''),(7,27,'config.json','gse-service','','{\n  \"server_addr\": \"\",\n  \"port\": 8090,\n \n  \"nodeman_domain\": \"st-nodeman\",\n  \"skip_auth\": false,\n  \"swagger_enable\": false,\n  \"data_base\": {\n    \"drive\": \"mysql\",\n    \"host\": \"127.0.0.1\",\n    \"port\": \"3306\",\n    \"user\": \"root\",\n    \"pwd\": \"mysql-password\",\n    \"database\": \"bo_nodeman\",\n    \"show_sql\": true\n  },\n  \"redis\": {\n    \"addrs\": \"127.0.0.1:26379,127.0.0.2:26379,127.0.0.3:26379\",\n    \"password\": \"redis-password\",\n    \"masterName\": \"mymaster\",\n    \"redisType\": \"sentinel\",\n    \"db\": 1\n  },\n \n  \"log_path\": \"/data/logs/bk_gse\",\n  \"mode\": \"dev\"\n}\n','3f6b4eaeaa03121a05b8fd8d0abd2dd0','2025-05-29 09:19:07','2025-05-29 09:19:07','nacos','10.5.168.174','U','st-observable',''),(9,29,'config.toml','n9e-service','','[global]\nRunMode = \"release\"\n[Log]\nDir = \"/data/service/n9e_service/log\"\nLevel = \"DEBUG\"\nOutput = \"file\"\nRotateSize=200\nRotateNum=10\nKeepHours=0\n[HTTP]\nHost = \"0.0.0.0\"\nPort = 17000\nCertFile = \"\"\nKeyFile = \"\"\nPrintAccessLog = false\nPProf = false\nExposeMetrics = true\nShutdownTimeout = 30\nMaxContentLength = 67108864\nReadTimeout = 20\nWriteTimeout = 600\nIdleTimeout = 120\nNoSignIn = false\n\n[HTTP.Pushgw]\nEnable = true\n# [HTTP.Pushgw.BasicAuth]\n# user001 = \"ccc26da7b9aba533cbb263a36c07dcc5\"\n\n[HTTP.Alert]\nEnable = true\n[HTTP.Alert.BasicAuth]\nuser001 = \"ccc26da7b9aba533cbb263a36c07dcc5\"\n\n[HTTP.Heartbeat]\nEnable = true\n# [HTTP.Heartbeat.BasicAuth]\n# user001 = \"ccc26da7b9aba533cbb263a36c07dcc5\"\n\n[HTTP.Service]\nEnable = true\n[HTTP.Service.BasicAuth]\nuser001 = \"ccc26da7b9aba533cbb263a36c07dcc5\"\n\n[HTTP.JWTAuth]\n# signing key\nSigningKey = \"5b94a0fd640fe2765af826acfe42d151\"\n# unit: min\nAccessExpired = 1500\n# unit: min\nRefreshExpired = 10080\nRedisKeyPrefix = \"/jwt/\"\n\n[HTTP.ProxyAuth]\n# if proxy auth enabled, jwt auth is disabled\nEnable = true\n# username key in http proxy heade\nHeaderUserNameKey = \"X-User-Name\"\nCookieTokenKey = \"bk_token\"\nTokenCheckURL = \"auth\"\nDefaultRoles = [\"Admin\"]\n\n[HTTP.APIGateway]\nAppCode = \"bk_iam\"\nAppSecret = \"05dc121d-ec79-491c-946c-4349eb9e364b\"\nUserName = \"admin\"\nFields = \"id,username,display_name,telephone,email\"\n\n[HTTP.RSA]\n# open RSA\nOpenRSA = false\n# RSA public key\nRSAPublicKeyPath = \"/etc/n9e/public.pem\"\n# RSA private key\nRSAPrivateKeyPath = \"/etc/n9e/private.pem\"\n# RSA private key password\nRSAPassWord = \"\"\n\n[HTTP.APIForService]\nEnable = true\n\n[HTTP.APIForAgent]\nEnable = true\n\n[HTTP.ThirdParty.GSE]\nDomain = \"st-gse\"\n\n[HTTP.ThirdParty.Nodeman]\nDomain = \"st-nodeman\"\n\n[HTTP.ThirdParty.Auth]\nDomain = \"auth\"\n\n[HTTP.ThirdParty.Res]\nDomain = \"resource-manager-service\"\n\n[HTTP.ThirdParty.Alarm]\nEventUploadUrl = \"alarm-all\"\nDialtestingEventUploadUrl = \"alarm-all\"\n#DialtestingCloseSendAlarm = false   #测试专用，是否上报拨测告警\n\n[DB]\n#DSN=\"dm://N9E:dm-password@127.0.0.1:5236?schema=N9E\"\n#Debug = false\n#DBType = \"dm\"\nDSN=\"root:mysql-password@tcp(127.0.0.1:3306)/n9e_v6?charset=utf8mb4&parseTime=True&loc=Local&allowNativePasswords=true\"\nDebug = false\nDBType = \"mysql\"\nMaxLifetime = 7200\nMaxOpenConns = 150\nMaxIdleConns = 50\nTablePrefix = \"\"\n\n[Redis]\n#redis单例模式配置\n#Address = \"127.0.0.1:6379\"\n#Password = \"redis-password\"\n#RedisType = \"\"\n\n#redis哨兵模式配置\nAddress = \"127.0.0.1:26379,127.0.0.2:26379,127.0.0.3:26379\"\nPassword = \"redis-password\"\nRedisType = \"sentinel\"\nMasterName = \"mymaster\"\n\n[Alert]\n[Alert.Heartbeat]\n# auto detect if blank\nIP = \"\"\n# unit ms\nInterval = 1000\nClusterName = \"default\"\n\n[Center]\nRumYamlFile = \"rum.yaml\"\n\n[Center.AnonymousAccess]\nPromQuerier = true\nAlertDetail = true\n\n[Pushgw]\n# use target labels in database instead of in series\nLabelRewrite = true\n\n[[Pushgw.Writers]]\n# Url = \"http://127.0.0.1:8480/insert/0/prometheus/api/v1/write\" # 集群的URL示例，不要删\n# Url = \"http://127.0.0.1:8428/api/v1/write\"   #单节点的URL示例，不要删\nUrl = \"http://127.0.0.1:8428/api/v1/write\"\n# Basic auth username\nBasicAuthUser = \"\"\n# Basic auth password\nBasicAuthPass = \"\"\n# timeout settings, unit: ms\nHeaders = [\"X-From\", \"n9e\"]\nTimeout = 10000\nDialTimeout = 3000\nTLSHandshakeTimeout = 30000\nExpectContinueTimeout = 1000\nIdleConnTimeout = 90000\n# time duration, unit: ms\nKeepAlive = 30000\nMaxConnsPerHost = 0\nMaxIdleConns = 100\nMaxIdleConnsPerHost = 100\n\n[DangerousCommand]\nShells = [\"expr\", \"rm\", \"mv\", \"shutdown\", \"reboot\", \"crontab\"]\nPythons = [\"os.remove\", \"shutil.move\", \"shutdown\", \"schedule.every\", \"threading.Timer\"]\nPython3s = [\"os.remove\", \"shutil.move\", \"shutdown\", \"schedule.every\", \"threading.Timer\"]\n\n[Extend]\nDialExportManySheet = false\nDialExportMaxDays = 7\nDialExportMaxTaskCount = 1000\nDialExportFailData = true\nTargetExportMaxDays = 7\n\n[ZheJiangThreshold]\nHost=[1,1,80] # [cpu, mem, disk] 整数，不可填小数\n[ZheJiangThreshold.Redis]\ndev=2\n\"测试集群\"=3\n[ZheJiangThreshold.Rocketmq]\ncluster1=3\ncluster2=1\n[ZheJiangThreshold.Fastdfs]\ncluster1 = [2,2] # [group数量，活跃server数量] 整数\ncluster2 = [1,1] # [group数量，活跃server数量] 整数\n\n[Doris.Datasource]\nDSN=\"doris-user:doris-password@tcp(127.0.0.1:9030)/n9e?charset=utf8mb4&parseTime=True&loc=Local&allowNativePasswords=true\"\nDebug = true\nDBType = \"doris\"\nMaxLifetime = 7200\nMaxOpenConns = 150\nMaxIdleConns = 50\nTablePrefix = \"\"\n\n[Doris.StreamLoad]\nHost=\"127.0.0.1\"\nPort=\"8030\"\nDatabase=\"n9e\"\nUser=\"doris-user\"\nPassword=\"doris-password\"\nMaxFilterRatio=0.0\nLoadToSingleTablet=false\nMergeMaxSizeMb=70\nMergeMaxWaitSecond=60\nConcurrentOperatorCount=10\nFileKeepHour=48','0e0aedabf4aebb96306f7c6f5811005b','2025-05-29 09:37:08','2025-05-29 09:37:09','nacos','10.5.168.174','U','st-observable',''),(19,31,'config-custom.yml','ST-LOG-PLATFORM','','st-log-platform:\n  config:\n    db:\n      url: 127.0.0.1 #数据库服务器ip\n      username: doris-user # 数据库用户\n      password:  doris-password # 数据库用户密码\n    kafka:\n      bootstrap-servers: 127.0.0.1:9092 # kafka部署地址\n    xxl-job:\n      admin-server-ip: 127.0.0.1 # xxl-job调度中心部署地址\n    grafana:\n      url: http://127.0.0.1:3000/d/ffb8ddd6-f2c9-4f6c-9e8d-8352cc99a798/nginx?orgId=1  # Grafana Nginx仪表盘地址\n    elasticsearch:\n      uris: 127.0.0.1:9200\n      username: elastic\n      password: elastic','c63fdf87318cb9d0a70fd63cdc53e75f','2025-05-29 09:45:37','2025-05-29 09:45:38','nacos','10.5.168.174','U','st-observable',''),(19,33,'config-custom.yml','ST-LOG-PLATFORM','','st-log-platform:\n  config:\n    db:\n      url: 172.30.94.79 #数据库服务器ip\n      username: observable # 数据库用户\n      password:  1qazZAQ! # 数据库用户密码\n    kafka:\n      bootstrap-servers: 172.30.94.79:9092 # kafka部署地址\n    xxl-job:\n      admin-server-ip: 172.30.94.79 # xxl-job调度中心部署地址\n    grafana:\n      url: http://172.30.94.79:3000/d/ffb8ddd6-f2c9-4f6c-9e8d-8352cc99a798/nginx?orgId=1  # Grafana Nginx仪表盘地址\n    elasticsearch:\n      uris: 172.30.94.79:9200\n      username: elastic\n      password: elastic','f799f034881e0ff5e771f7dbbf7c22cb','2025-05-29 10:49:42','2025-05-29 10:49:43','nacos','10.5.168.174','U','st-observable',''),(17,35,'application-startrace.yml','ST-LOG-PLATFORM','','st-log-platform:\n  config:\n    kafka:\n      log-record-topic: test_topic # 日志记录使用的Topic\n      consumer:\n        topics-to-listen: test_topic # kafka消费topic, 默认会消费log-record-topic, 在这里可以添加额外需要消费的Topic\n    xxl-job:\n      enabled: true # 是否启用xxl-job\n      accessToken: aafb230a-1bef-411d-8853-5f3d4edebb95 # 执行器的通信令牌，非空时启用\n    storage:\n      type: doris\n    stack-error:\n      type: regex # 错误堆栈信息解析方式\n  auth-enable: true # 是否开启权限认证\n  deploy-job-enable: true\n  deploy-alarm-platform: true # 是否部署了统一告警平台\n  application-add-url: http://127.0.0.1:9005/resource/sys/application/insert # resource服务地址\n  alarm:\n    alarm-server: alarm-all # 告警平台服务地址\n    alarm-server-path: alarm # 告警平台服务Http请求前缀\n    send-alarm:\n      core-pool-size: 1\n      max-pool-size: 2\n  access:\n    vector-kafka-bootstrap-servers: ${spring.kafka.bootstrap-servers}\n    vector-topic: ${st-log-platform.config.kafka.log-record-topic} # vector写入的kafka topic\n  http-server:\n    thread-pool:\n      core-pool-size: 5\n      max-pool-size: 10\n      queue-capacity-size: 5000\n\n\nserver:\n  port: 8100\n  servlet:\n    context-path: /log-platform\n\nspring:\n  datasource:\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://${st-log-platform.config.db.url}:9030/log_platform?characterEncoding=utf-8&useSSL=false&serverTimezone=Asia/Shanghai\n    username: ${st-log-platform.config.db.username}\n    password: ${st-log-platform.config.db.password}\n    hikari:\n      maximum-pool-size: 60  # 最大连接数，默认值10\n      minimum-idle: 10  # 最小空闲连接数，默认值10\n      connection-timeout: 60000 # 连接超时时间（毫秒），默认值60000（30秒）\n      idle-timeout: 600000  # 空闲连接超时时间，默认值600000（10分钟）\n      max-lifetime: 3600000 # 连接最大存活时间，默认值1800000（30分钟）\n      connection-test-query: select 1 # 连接测试查询\n  jackson:\n    date-format: yyyy-MM-dd HH:mm:ss.SSS\n    time-zone: GMT+8\n  kafka:\n    bootstrap-servers: ${st-log-platform.config.kafka.bootstrap-servers}\n    listener:\n      concurrency: 3\n    consumer:\n      enable-auto-commit: false\n      key-deserializer: org.apache.kafka.common.serialization.StringDeserializer\n      value-deserializer: org.apache.kafka.common.serialization.StringDeserializer\n      auto-offset-reset: latest\n      max-poll-records: 10000\n      fetch-max-bytes: 10485760\n      max-partition-fetch-bytes: 10485760\n      fetch-max-wait-ms: 15000\n      fetch-min-bytes: 5242880\n      group-id: log-consumer\n      topics-to-listen: ${st-log-platform.config.kafka.log-record-topic},${st-log-platform.config.kafka.consumer.topics-to-listen}\n    producer:\n      key-serializer: org.apache.kafka.common.serialization.StringSerializer\n      value-serializer: org.apache.kafka.common.serialization.StringSerializer\n      batch-size: 163840  # single request 批处理大小（以字节为单位），默认16KB = 16384\n      properties.linger.ms: 500\n  config:\n    import: config-custom.yml\n\nmybatis-plus:\n  global-config:\n    enable-sql-runner: true\n  configuration:\n    map-underscore-to-camel-case: false\n    call-setters-on-nulls: true\n    #log-impl: org.apache.ibatis.logging.stdout.StdOutImpl #开启sql日志, 生产环境关闭\n\nmanagement:\n  endpoints:\n    enabled-by-default: false\n  endpoint:\n    health:\n      enabled: true\n  health:\n    elasticsearch:\n      enabled: false #关闭es健康自测，防止doris启动报错\n\n# xxl-job配置\nsop:\n  xxl-job:\n    enabled: ${st-log-platform.config.xxl-job.enabled}\n    admin:\n      addresses: http://${st-log-platform.config.xxl-job.admin-server-ip}:8101/xxl-job-admin # 调度中心部署地址-如调度中心集群部署存在多个地址则用逗号分隔\n    accessToken: ${st-log-platform.config.xxl-job.accessToken} # 执行器的通信令牌，非空时启用\n    executor:\n      appname: ${spring.application.name} # 与xxl-job-admin配置的appname一致\n      address:\n      ip:  # 执行器的IP地址，执行器IP默认为空，表示自动获取IP\n      port: 9999  # 执行器的端口号，默认值为9999\n      logpath: logs/xxljob\n      logretentiondays: 7\n\ndoris:\n  stream-load:\n    datasource:\n      host: ${st-log-platform.config.db.url}\n      port: 8030\n      database: log_platform\n      user: ${st-log-platform.config.db.username}\n      password: ${st-log-platform.config.db.password}\n    data:\n      dir: /data/public/st-logplatform-service/log-data-file/\n      fail-file-keep-hour: 48\n      fail-file-clear-cron: 0 0 2 * * ?\n      merge:\n        core-pool-size: 1\n        max-pool-size: 1\n        concurrent-operator-count: 1\n        max-size-mb: 70\n        max-wait-second: 60\n    send:\n      async-enable: true  #是否启用异步导入\n      max-filter-ratio: 0  # 最大容忍可过滤（数据不规范等原因）的数据比例,取值范围是0~1,例如:0.1\n      core-pool-size: 2\n      max-pool-size: 2\n    retry:\n      core-pool-size: 1\n      max-pool-size: 1\n      fail-send-cron: 0 0 */1 * * ?  #doris-stream-load失败重试定时cron\nes:\n  storage-async:\n    split:\n      core-pool-size: 1\n      max-pool-size: 2\n      queue-capacity-size: 50\n      max-wait-time: 60\n    send:\n      core-pool-size: 1\n      max-pool-size: 2\n      listSize: 500      \n\n','3d3ae6433b90632fbbab7de58e2d1ab7','2025-05-29 10:55:27','2025-05-29 10:55:28','nacos','10.5.168.174','U','st-observable',''),(17,37,'application-startrace.yml','ST-LOG-PLATFORM','','st-log-platform:\n  config:\n    kafka:\n      log-record-topic: log_record_topic # 日志记录使用的Topic\n      consumer:\n        topics-to-listen:  # kafka消费topic, 默认会消费log-record-topic, 在这里可以添加额外需要消费的Topic\n    xxl-job:\n      enabled: true # 是否启用xxl-job\n      accessToken: aafb230a-1bef-411d-8853-5f3d4edebb95 # 执行器的通信令牌，非空时启用\n    storage:\n      type: doris\n    stack-error:\n      type: regex # 错误堆栈信息解析方式\n  auth-enable: true # 是否开启权限认证\n  deploy-job-enable: true\n  deploy-alarm-platform: true # 是否部署了统一告警平台\n  application-add-url: http://127.0.0.1:9005/resource/sys/application/insert # resource服务地址\n  alarm:\n    alarm-server: alarm-all # 告警平台服务地址\n    alarm-server-path: alarm # 告警平台服务Http请求前缀\n    send-alarm:\n      core-pool-size: 1\n      max-pool-size: 2\n  access:\n    vector-kafka-bootstrap-servers: ${spring.kafka.bootstrap-servers}\n    vector-topic: ${st-log-platform.config.kafka.log-record-topic} # vector写入的kafka topic